/* ================= API ================= */
let TOKEN=store.get('baTok'),ME=null,GUEST=false;
async function api(a,body,extra){const bt=setTimeout(()=>document.body.classList.add('busy'),180);try{return await api0(a,body,extra)}finally{clearTimeout(bt);if(!--API_N)document.body.classList.remove('busy')}}
let API_N=0;async function api0(a,body,extra){API_N++;const h={'Content-Type':'application/json'};if(TOKEN)h['X-BA-Token']=TOKEN;const r=await fetch(API+'?a='+a+(extra||''),{method:body?'POST':'GET',headers:h,body:body?JSON.stringify(body):undefined,cache:'no-store'});let j=null;try{j=await r.json()}catch(e){}if(!j)throw new Error('net');if(!j.ok){const e=new Error(j.error||'err');e.data=j;throw e}return j}
/* v38 — konfigurasi jarak jauh (dari Kontrol Gim di Aplikasi Khusus) + sinyal kehadiran */
let CFG={};const SID=(()=>{try{let s=sessionStorage.getItem('baSid');if(!s){s=(Math.random().toString(36).slice(2,10)+Date.now().toString(36)).slice(0,20);sessionStorage.setItem('baSid',s)}return s}catch(e){return(Math.random().toString(36).slice(2,10)+Date.now().toString(36)).slice(0,20)}})();
function cfgApply(c){if(!c||typeof c!=='object')return;CFG=c;
 const g=$('aGuest');if(g)g.classList.toggle('hidden',c.guestOk===false);const r=$('tbReg');if(r){const off=c.regOpen===false||!!c.maint;r.classList.toggle('hidden',off);if(off&&r.classList.contains('on')&&$('tbLogin'))$('tbLogin').click()}
 const mx=c.maxSpeed||3;['sp1','sp2','sp3'].forEach((id,i)=>{const b=$(id);if(b)b.classList.toggle('hidden',i+1>mx)});if(S&&speed>mx)setSpeed(mx);
 let ov=$('maintOv');if(c.maint){if(!ov){ov=document.createElement('div');ov.id='maintOv';document.body.appendChild(ov)}ov.innerHTML=`<div class="box"><h2>🛠 ${L2('Sedang pemeliharaan','Under maintenance')}</h2><p></p><small>${L2('Halaman akan lanjut otomatis setelah selesai.','This page resumes automatically when done.')}</small></div>`;ov.querySelector('p').textContent=c.maintMsg||L2('Babat Alas sedang diperbarui. Silakan kembali sebentar lagi.','Babat Alas is being updated. Please come back shortly.');if(S&&speed)setSpeed(0)}else if(ov)ov.remove();
 let an=$('annBar');const seen=(()=>{try{return localStorage.getItem('baAnn')}catch(e){return null}})();if(c.announce&&c.announceId&&seen!==String(c.announceId)){if(!an){an=document.createElement('div');an.id='annBar';document.body.appendChild(an)}an.innerHTML='<span>📢 </span><b></b><button aria-label="Tutup">✕</button>';an.querySelector('b').textContent=c.announce;an.querySelector('button').onclick=()=>{try{localStorage.setItem('baAnn',String(c.announceId))}catch(e){}an.remove()}}else if(an&&!c.announce)an.remove()}
async function cfgLoad(){try{const j=await api('cfg');cfgApply(j.cfg)}catch(e){}}
async function hb(){if(document.hidden||!S||S.scen||VISIT)return;try{const L=S.loc||{};const j=await api('hb',{sid:SID,name:(S.meta&&S.meta.name)||'',loc:L.name||'',cc:L.cc||'',lat:L.lat||0,lon:L.lon||0,era:S.era||0,kk:S.kk||0,dev:/iPad|Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1?'iPad':/iPhone/.test(navigator.userAgent)?'iPhone':/Android/.test(navigator.userAgent)?'Android':'Desktop',scr:innerWidth+'x'+innerHeight});cfgApply(j.cfg);dealNotify(j.dealIn|0)}catch(e){}}
/** v51j: kunjungi (lihat saja) kampung pemain lain — keadaan kampung sendiri disimpan dulu, simulasi & penyimpanan berhenti selama kunjungan */
let VISIT=null;
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-visit]');if(!b)return;e.preventDefault();e.stopPropagation();visit(b.dataset.visit,b.dataset.vn||'')},true);
async function visit(pid,nm){if(!S||GUEST||S.scen){toast(L2('Masuk dengan akun dan buka kampungmu dulu.','Sign in and open your kampung first.'));return}
 let j;try{toast('👁 '+L2('Memuat kampung','Loading kampung')+' '+(nm||'')+'…');if(!VISIT)await safeSave();j=await api('peek',null,'&pid='+pid)}catch(e){toast(e&&e.message==='no_user'?L2('Kampung ini belum dapat dilihat.','This kampung cannot be viewed yet.'):t('errNet'));return}
 if(j.me){toast(L2('Ini kampungmu sendiri.','This is your own kampung.'));return}
 const st=j.state;if(!st.loc||!st.meta){toast(L2('Kampung ini belum dapat dilihat.','This kampung cannot be viewed yet.'));return}st.char=st.char||{name:j.who};st.links=st.links||[];st.stock=st.stock||{};st.clk=st.clk||{h:10,d:1};
 if(!VISIT)VISIT={me:S,spd:speed,tool};S=st;tool='info';$('modal').classList.add('hidden');$('menu').classList.add('hidden');$('info').classList.add('hidden');
 try{R3.world();R3.daylight((S.clk.h||10)/24);if(S.wx)R3.weather(S.wx,seasonOf(calM()))}catch(e){console.warn(e)}try{updHUD()}catch(e){}try{renderMissions()}catch(e){}
 document.body.classList.add('visiting');let bn=$('visBan');if(!bn){bn=document.createElement('div');bn.id='visBan';document.body.appendChild(bn)}
 bn.innerHTML=`<span>👁 ${L2('Melihat kampung','Viewing kampung')} <b>${esc(S.meta&&S.meta.name||nm)}</b> · ${esc(j.who)}${j.kampus?' · '+esc(j.kampus):''} · ${L2('Era','Era')} ${S.era||1} · ${S.kk||0} KK · ${L2('skor','score')} ${S.score||0}</span><button class="bigbtn gold" id="visBack">⬅ ${L2('Kembali ke kampungku','Back to my kampung')}</button>`;$('visBack').onclick=()=>visitEnd()}
function visitEnd(quiet){if(!VISIT)return;const v=VISIT;VISIT=null;S=v.me;tool=v.tool||'info';document.body.classList.remove('visiting');const bn=$('visBan');if(bn)bn.remove();if(quiet)return;$('info').classList.add('hidden');
 try{R3.world();R3.daylight(S.clk.h/24);if(S.wx)R3.weather(S.wx,seasonOf(calM()))}catch(e){console.warn(e)}try{updHUD();renderBar();renderMissions()}catch(e){}toast(L2('Kembali ke kampungmu.','Back to your kampung.'))}
/** v51i: notifikasi tawaran perjanjian dagang masuk — toast + titik merah di ☰ dan di Jaringan dagang */
let DEAL_N=-1;function dealNotify(n){const prev=DEAL_N;DEAL_N=n;document.body.classList.toggle('dealIn',n>0);const mb=document.getElementById('mBtn');if(mb)mb.dataset.n=n>0?n:'';const mn=document.getElementById('mNet');if(mn)mn.dataset.n=n>0?n:'';
 if(n>0&&n>Math.max(prev,0)){try{Snd.play('coin')}catch(e){}const el=document.createElement('div');el.className='dealToast';el.innerHTML=`🤝 <b>${n>1?L2(n+' tawaran perjanjian dagang',''+n+' trade agreement offers'):L2('Ada tawaran perjanjian dagang','A trade agreement offer')}</b> ${L2('menunggu jawabanmu.','is waiting for your reply.')} <button class="bigbtn gold">${L2('Lihat','View')}</button><button class="x" aria-label="${L2('Tutup','Close')}">✕</button>`;document.body.appendChild(el);const rm=()=>el.remove();el.querySelector('.x').onclick=rm;el.querySelector('.bigbtn').onclick=()=>{rm();if(S&&typeof network==='function'){$('menu').classList.add('hidden');network()}};setTimeout(rm,20000)}}
setInterval(()=>{if(S)hb();else if(!document.hidden)cfgLoad()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)(S?hb:cfgLoad)()});cfgLoad();

