function rng(seed){let a=seed>>>0;return()=>{a=(a+0x6D2B79F5)>>>0;let x=a;x=Math.imul(x^(x>>>15),x|1);x^=x+Math.imul(x^(x>>>7),x|61);return((x^(x>>>14))>>>0)/4294967296}}
function hash2(x,y,s){let h=(x*374761393+y*668265263+s*1442695041)>>>0;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}
function noise(x,y,s){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi,f=t=>t*t*(3-2*t);const a=hash2(xi,yi,s),b=hash2(xi+1,yi,s),c=hash2(xi,yi+1,s),d=hash2(xi+1,yi+1,s);return a+(b-a)*f(xf)+(c-a)*f(yf)+(a-b-c+d)*f(xf)*f(yf)}
function fbm(x,y,s){return noise(x,y,s)*.6+noise(x*2.1,y*2.1,s+7)*.28+noise(x*4.3,y*4.3,s+13)*.12}
function seedOf(loc){return (Math.round(loc.lat*1e4)*73856093^Math.round(loc.lon*1e4)*19349663)>>>0}
/** Medan: tinggi per titik sudut (N+1)², sungai, hutan. Hasil deterministik dari seed. */
function genWorld(seed){const r=rng(seed),H=[],land=[];const hasRiver=r()<.8,horiz=r()<.5;let rp=8+Math.floor(r()*(N-16)),river=new Set();
 if(hasRiver){for(let i=0;i<N;i++){rp+=Math.round((r()-.5)*2.2);rp=Math.max(3,Math.min(N-4,rp));const w=r()<.3?3:2;for(let k=0;k<w;k++){const a=i,b=rp+k;river.add(horiz?b+','+a:a+','+b)}}}
 for(let y=0;y<=N;y++){H.push([]);for(let x=0;x<=N;x++)H[y].push(.55+fbm(x/11,y/11,seed%997)*2.6)}
 for(let y=0;y<N;y++){land.push([]);for(let x=0;x<N;x++){const k=x+','+y;const dc=Math.hypot(x-N/2,y-N/2);land[y].push(river.has(k)?'W':(fbm(x/7,y/7,seed%991+5)+(dc<6?-.3:dc<10?-.1:0)>.44?'F':'G'))}}
 // sungai lebih rendah
 river.forEach(k=>{const [x,y]=k.split(',').map(Number);[[0,0],[1,0],[0,1],[1,1]].forEach(([dx,dy])=>{H[y+dy][x+dx]=Math.min(H[y+dy][x+dx],0)})});
 return {H,land}}
function newState(loc,ch,name){const seed=seedOf(loc),w=genWorld(seed);return {v:1,seed,loc,char:ch,m0:new Date().getMonth(),clk:{h:7,d:1},wx:'cerah',links:[],stock:{},meta:{name,created:Date.now()},own:{x0:(N-START)/2,y0:(N-START)/2,x1:(N+START)/2,y1:(N+START)/2},exp:0,era:1,t:0,res:{coin:667,wood:60,food:60,stone:20,iron:0},kk:2,happy:62,coh:60,
 land:w.land.map(r=>r.join('')),b:[],nid:1,flags:{},done:[],ev:{dry:0},stats:{cleared:0},score:0}}


/* ================= v0.3: kalender, musim, cuaca, pembangunan bertahap, mata uang, komoditas, jaringan ================= */
/* kurs perkiraan untuk permainan: 1 satuan kas ≈ Rp 150 juta (kas awal ≈ Rp 100 miliar) */
const CUR={ID:['Rp',150000000,'id-ID'],MY:['RM',45000,'ms-MY'],SG:['S$',13000,'en-SG'],JP:['¥',1500000,'ja-JP'],PH:['₱',550000,'en-PH'],TH:['฿',330000,'th-TH'],VN:['₫',250000000,'vi-VN'],US:['US$',10000,'en-US'],GB:['£',8000,'en-GB'],AU:['A$',15000,'en-AU'],CN:['¥',70000,'zh-CN'],KR:['₩',13000000,'ko-KR'],IN:['₹',850000,'en-IN'],MA:['MAD',95000,'fr-MA'],EUR:['€',9000,'de-DE'],XX:['US$',10000,'en-US']};
const EUROZ=['NL','DE','FR','BE','IT','ES','AT','PT','FI','IE','GR','SK','SI','LU','EE','LV','LT','HR','MT','CY'];
const curOf=()=>CUR[S&&S.loc?S.loc.cc:'XX']||(EUROZ.includes(S&&S.loc&&S.loc.cc)?CUR.EUR:CUR.XX);
function money(v,short){const [sym,rate,loc]=curOf();const x=v*rate,a=Math.abs(x);let s;
 if(short&&a>=1e9)s=(x/1e9).toLocaleString(loc,{maximumFractionDigits:1})+(lang==='en'?'B':' M');else if(short&&a>=1e6)s=(x/1e6).toLocaleString(loc,{maximumFractionDigits:1})+(lang==='en'?'M':' jt');else if(short&&a>=1e4)s=(x/1e3).toLocaleString(loc,{maximumFractionDigits:0})+(lang==='en'?'k':' rb');else s=Math.round(x).toLocaleString(loc);return sym+' '+s}
/* musim per iklim & belahan bumi */
const SEASN={id:{hujan:'Musim hujan',kemarau:'Musim kemarau',pancaroba:'Pancaroba',semi:'Musim semi',panas:'Musim panas',gugur:'Musim gugur',dingin:'Musim dingin'},en:{hujan:'Wet season',kemarau:'Dry season',pancaroba:'Transition',semi:'Spring',panas:'Summer',gugur:'Autumn',dingin:'Winter'}};
const SEAS_IC={hujan:'🌧️',kemarau:'☀️',pancaroba:'🌦️',semi:'🌸',panas:'🌞',gugur:'🍂',dingin:'❄️'};
const calM=()=>((S.m0||0)+S.t)%12, calY=()=>Math.floor(((S.m0||0)+S.t)/12)+1;
function seasonOf(m){const cl=S.loc.climate,lat=S.loc.lat;if(cl==='trop'||cl==='tropdry'){const south=lat<0;
  const wet=south?[10,11,0,1,2]:[4,5,6,7,8,9].slice(cl==='tropdry'?1:0,cl==='tropdry'?5:6),tr=south?[3,9]:[3,10];if(wet.includes(m))return 'hujan';if(tr.includes(m))return 'pancaroba';return 'kemarau'}
 const nh=lat>=0,mm=nh?m:(m+6)%12;return mm>=2&&mm<=4?'semi':mm>=5&&mm<=7?'panas':mm>=8&&mm<=10?'gugur':'dingin'}
const WXN={id:{cerah:'Cerah',berawan:'Berawan',gerimis:'Gerimis',hujan:'Hujan',badai:'Hujan badai',kabut:'Berkabut',salju:'Salju',panas:'Terik'},en:{cerah:'Clear',berawan:'Cloudy',gerimis:'Drizzle',hujan:'Rain',badai:'Thunderstorm',kabut:'Foggy',salju:'Snow',panas:'Scorching'}};
const WX_IC={cerah:'☀️',berawan:'⛅',gerimis:'🌦️',hujan:'🌧️',badai:'⛈️',kabut:'🌫️',salju:'🌨️',panas:'🔥'};
function rollWeather(){const s=seasonOf(calM()),r=Math.random();const T={hujan:[['hujan',.35],['gerimis',.2],['badai',.12],['berawan',.2],['cerah',.13]],kemarau:[['cerah',.55],['panas',.2],['berawan',.2],['gerimis',.05]],pancaroba:[['berawan',.3],['cerah',.25],['hujan',.2],['badai',.1],['gerimis',.15]],
  semi:[['cerah',.35],['berawan',.3],['gerimis',.2],['hujan',.15]],panas:[['cerah',.5],['panas',.2],['berawan',.15],['badai',.15]],gugur:[['berawan',.35],['hujan',.25],['kabut',.2],['cerah',.2]],dingin:[['salju',.4],['berawan',.25],['kabut',.15],['cerah',.2]]}[s];
 let a=0;for(const [k,p] of T){a+=p;if(r<=a)return k}return 'cerah'}
/* lahan: kesuburan & kemiringan */
const fert=(x,y)=>.6+fbm(x/9,y/9,S.seed%983+11)*.9;
const slope=(x,y)=>{const H=R3.H;if(!H)return 0;const a=[H[y][x],H[y][x+1],H[y+1][x],H[y+1][x+1]];return Math.max(...a)-Math.min(...a)};
/* komoditas khas kampung: alam + budaya */
const COMN={id:{padi:'Padi',kelapa:'Kelapa',pisang:'Pisang',kopi:'Kopi',teh:'Teh',jagung:'Jagung',ternak:'Ternak',ikan:'Ikan',kayu:'Kayu & rotan',madu:'Madu hutan',sayur:'Sayur',gandum:'Gandum',apel:'Apel',susu:'Susu',batik:'Batik',anyaman:'Anyaman bambu',gerabah:'Gerabah',ukir:'Ukiran kayu',tenun:'Tenun',songket:'Songket',keramik:'Keramik',keju:'Keju',kerajinan:'Kerajinan kayu',beras:'Beras'},
 en:{padi:'Rice',kelapa:'Coconut',pisang:'Banana',kopi:'Coffee',teh:'Tea',jagung:'Maize',ternak:'Livestock',ikan:'Fish',kayu:'Timber & rattan',madu:'Forest honey',sayur:'Vegetables',gandum:'Wheat',apel:'Apples',susu:'Milk',batik:'Batik',anyaman:'Bamboo weaving',gerabah:'Earthenware',ukir:'Woodcarving',tenun:'Woven cloth',songket:'Songket',keramik:'Ceramics',keju:'Cheese',kerajinan:'Woodcraft',beras:'Rice'}};
const COM_IC={padi:'🌾',kelapa:'🥥',pisang:'🍌',kopi:'☕',teh:'🍵',jagung:'🌽',ternak:'🐄',ikan:'🐟',kayu:'🪵',madu:'🍯',sayur:'🥬',gandum:'🌾',apel:'🍎',susu:'🥛',batik:'🧵',anyaman:'🧺',gerabah:'🏺',ukir:'🪚',tenun:'🧶',songket:'🧶',keramik:'🏺',keju:'🧀',kerajinan:'🪚'};
const PRICE={padi:2,kelapa:2,pisang:1.5,kopi:4,teh:3.5,jagung:1.8,ternak:5,ikan:3,kayu:2.5,madu:6,sayur:2,gandum:2,apel:3,susu:3,batik:8,anyaman:5,gerabah:5,ukir:9,tenun:8,songket:9,keramik:7,keju:7,kerajinan:6};
function ecoProfile(st){const cl=st.loc.climate,cc=st.loc.cc,r=rng(st.seed+5),land=st.land.join(''),water=land.includes('W'),forest=(land.split('F').length-1)/land.length;
 const crop=cl==='trop'?(r()<.45?'kopi':r()<.5?'kelapa':'pisang'):cl==='tropdry'?(r()<.5?'jagung':'ternak'):cl==='sub'?(r()<.5?'teh':'sayur'):(r()<.5?'apel':'susu');
 const craftL={ID:['batik','anyaman','gerabah','ukir','tenun'],MY:['songket','anyaman'],JP:['keramik','kerajinan'],PH:['anyaman','kerajinan'],NL:['keju','keramik'],FR:['keju'],DE:['kerajinan']}[cc]||(EUROZ.includes(cc)?['keju','keramik']:['kerajinan']);
 const craft=craftL[Math.floor(r()*craftL.length)];const nat=[];if(water)nat.push('ikan');if(forest>.25)nat.push(r()<.5?'madu':'kayu');
 return {staple:cl==='temp'?'gandum':cl==='tropdry'?'jagung':'padi',crop,craft,nat}}
/* kampung tetangga (NPC) untuk jaringan dagang */
const SYL={ID:[['Sumber','Karang','Wono','Tegal','Sido','Ngadi','Tirto','Pandan','Kali','Rejo'],['rejo','sari','mulyo','agung','harjo','wangi','asri','makmur','jati','kerto']],MY:[['Kampung ','Sungai ','Bukit ','Batu ','Padang '],['Baru','Raja','Melati','Jaya','Indah']],JP:[['Kami','Shimo','Naka','Kita','Minami'],['mura','sato','kawa','yama','hara']],XX:[['North','South','Old','New','Green'],['field','brook','wood','ford','haven']]};
function npcVillages(st){const r=rng(st.seed+9),L=SYL[st.loc.cc]||SYL.XX,P=ecoProfile(st);const all=Object.keys(PRICE);const out=[];
 for(let i=0;i<5;i++){const nm=L[0][Math.floor(r()*L[0].length)]+L[1][Math.floor(r()*L[1].length)];const want=all.filter(k=>k!==P.crop&&k!==P.craft&&r()<.25).slice(0,3);if(!want.length)want.push(P.craft);
  out.push({id:'npc'+i,name:(st.loc.cc==='ID'?'Desa ':'')+nm,km:+(2+r()*18).toFixed(1),want:[P.crop,P.craft,...P.nat].filter(()=>r()<.7).concat(want).slice(0,4),cost:20+Math.floor(r()*30)})}return out}


/* ---------- perdagangan bulanan ---------- */
function tradeMonth(staff,smul){const P=S.eco||(S.eco=ecoProfile(S)),out={income:0,items:[]};const kom=count('kom'),mk=lvC('market');const links=(S.links||[]).length,mult=1+.12*Math.min(links,8)+(kom?.15:0)+.1*Math.min(count('dermaga'),3)+konek()/250+umkmBoost()*.5;
 const prod={};const add=(k,v)=>{prod[k]=(prod[k]||0)+v};built().forEach(b=>{if(b.t==='kandang'){add('telur',2*staff*LVM(b));add('ternak',.5*staff*LVM(b))}if(b.t==='peternakan'){add('susu',3*staff*LVM(b));add('ternak',1.5*staff*LVM(b))}if(b.t==='dapur'&&S.res.food>25){const u=Math.min(4*staff,S.res.food-25);S.res.food-=u;add('olahan',u)}if(b.t==='kebun')add(P.crop,6*staff*smul*fert(b.x,b.y)*LVM(b));if(b.t==='bengkel')add(P.craft,3*staff*LVM(b));if(b.t==='pond')add('ikan',1.5*staff*LVM(b))});
 if(P.nat.includes('madu'))add('madu',Math.min(3,(S.land.join('').split('F').length-1)/2500));
 for(const k in prod){S.stock[k]=(S.stock[k]||0)+prod[k]}
 /* tanpa pasar & tetangga: pedagang keliling membeli sedikit dengan harga lebih rendah */
 const ped=!mk&&!links;const cap=(mk?14:0)+links*10+(ped?6:2);let sold=0;
 for(const k in S.stock){const q=Math.min(S.stock[k],Math.max(0,cap-sold));if(q<=0)continue;const want=(S.links||[]).some(l=>(l.want||[]).includes(k))?1.3:1;const v=q*(PRICE[k]||2)*.5*mult*want*(ped?.7:1);S.stock[k]-=q;sold+=q;out.income+=v;out.items.push([k,+q.toFixed(1),Math.round(v)])}
 if(S.res.wood>40){const q=Math.min(8,Math.floor(S.res.wood-40));if(q>0){S.res.wood-=q;const v=q*.6*mult*(ped?.7:1);out.income+=v;out.items.push(['kayu',q,Math.round(v)])}}
 out.income=Math.min(Math.round(out.income),5+6*mk+10*(count('kebun')+count('bengkel')+count('pond')+count('kandang')+count('peternakan')+count('dapur'))+8*links+8+6*S.b.filter(b=>(b.lv||1)>1&&UPG[b.t]&&b.t!=='house'&&b.t!=='barn').length);return out}
/* ---------- hari: cuaca & pembangunan ---------- */
/* v46d: pertumbuhan KK dicek tiap 5 hari (6× sebulan) dan tambahannya sebanding sisa kapasitas rumah (1 s.d. ⌈sisa/3⌉), bukan maks. +1 per bulan */
/** alasan KK tidak bertambah saat ini: [kunci, teks] (kosong = syarat terpenuhi) */
function growWhy(){const w=[],cap=popCap();if(cap<=S.kk)w.push(['cap',L2(`Rumah penuh (${S.kk}/${cap}). Bangun rumah baru atau naikkan level rumah.`,`Houses are full (${S.kk}/${cap}). Build new houses or upgrade them.`)]);
 if(S.happy<50)w.push(['happy',L2(`Kebahagiaan ${Math.round(S.happy)} (perlu ≥ 50). Dekatkan rumah ke sumur (≤ 5 petak) dan jaga pangan tetap surplus.`,`Happiness ${Math.round(S.happy)} (needs ≥ 50). Keep houses within 5 tiles of a well and food in surplus.`)]);
 if(S.res.food<=S.kk*2)w.push(['food',L2(`Pangan ${Math.floor(S.res.food)} (perlu > ${S.kk*2} = 2 × KK). Tambah ladang/kebun dan bangun lumbung untuk menyimpan.`,`Food ${Math.floor(S.res.food)} (needs > ${S.kk*2} = 2 × households). Add fields and build a granary to store it.`)]);return w}
/** panel Misi: status pertumbuhan warga & progres naik era, agar pemain tahu kenapa KK (tidak) bertambah */
function growPanel(){const cap=popCap(),why=growWhy(),nx=S.era+1,need=ERA_NEED[nx];
 return `<div class="grow"><b>👪 ${L2('Pertumbuhan warga','Population growth')}</b> <span>${S.kk} KK · ${L2('kapasitas','capacity')} ${cap}</span>`+
  (why.length?why.map(([,m])=>`<div class="gw bad">⛔ ${esc(m)}</div>`).join(''):`<div class="gw ok">✅ ${L2('Syarat terpenuhi: warga baru bisa datang pada pengecekan berikutnya.','Conditions met: new households can arrive at the next check.')}</div>`)+
  `<small>${L2('Dicek tiap 5 hari permainan ≈ 2 mnt di ⏩⏩, 12 mnt di ⏩, 2 jam di ▶.','Checked every 5 game days ≈ 2 min at ⏩⏩, 12 min at ⏩, 2 h at ▶.')}</small>`+
  (need?`<div class="gw">⬆ ${L2('Menuju','Next:')} <b>${t('eras')[nx-1]}</b>: `+need.map(([a,b,f,n])=>{const v=f();return `<span class="${v>=n?'ok':'bad'}">${lang==='en'?b:a} ${Math.min(v,n)}/${n}</span>`}).join(' · ')+'</div>':'')+'</div>'}
function growKK(){let intro=false;if(!S._gwIntro){S._gwIntro=1;intro=true;advise(L2('Warga baru datang tiap 3 hari permainan bila ada rumah kosong, kebahagiaan ≥ 50, dan pangan lebih dari 2 × KK. Lihat “Pertumbuhan warga” di panel Misi; pakai ⏩ untuk mempercepat waktu.','New households arrive every 3 game days if there are empty houses, happiness ≥ 50 and food above 2 × households. See “Population growth” in the Missions panel; use ⏩ to speed up time.'),'elder')}
 const why=growWhy();if(why.length){const k=why.map(w=>w[0]).join();if(k!==S._gwWhy||S.t-(S._gwAt||0)>=6){S._gwWhy=k;S._gwAt=S.t;if(!intro)advise(L2('Warga belum bertambah: ','No new households yet: ')+why[0][1],'eco')}return 0}S._gwWhy='';
 const free=popCap()-S.kk;if(Math.random()>=(.8+(count('sekolah')?.15:0)))return 0;const g=Math.min(free,1+Math.floor(Math.random()*Math.ceil(free/2)));S.kk+=g;return g}
function dayTick(){if(S.clk.d%3===0&&S.clk.d<30){if(growKK()){dirty=true;updHUD();checkMissions();checkEra()}else renderMissions()}setTimeout(tutCheck,0);S.wx=rollWeather();R3.weather(S.wx,seasonOf(calM()));if(S.wx==='badai'&&Math.random()<.15)advise(lang==='en'?'Thunderstorm! Keep away from the river.':'Hujan badai! Jauhi tepi sungai.','eng');
 // pembangunan: tiap lokasi butuh 2 tukang; tukang = pekerja yang belum bekerja
 }
const rushCost=b=>Math.max(1,Math.ceil(b.bt*b.w*b.h*.25)),rushWood=b=>Math.ceil(b.bt*1.5);
function rush(b){const c=rushCost(b);const wd=rushWood(b);if(S.res.coin<c){toast(t('noMoney'));Snd.play('err');return}if(S.res.wood<wd){toast(t('noWood'));Snd.play('err');return}
 S.res.wood-=wd;S.res.coin-=c;delete b.bt;R3.delB(b.id);R3.addB(b);Snd.play('build');Snd.play('coin');if(b.t==='house')R3.villagers();after();$('info').classList.add('hidden')}
/* ---------- panel jaringan dagang ---------- */
/** perjanjian dagang dua arah: ambil dari server, sinkronkan ke S.links (tiap perjanjian aktif = satu jalur dagang) */
async function syncDeals(){if(GUEST||!TOKEN||!S)return [];let L=[];try{L=(await api('deals')).list||[]}catch(e){return S._deals||[]}S._deals=L;S.links=(S.links||[]).filter(l=>!l.deal||L.some(d=>d.st==='active'&&'deal_'+d.id===l.id));
 L.filter(d=>d.st==='active').forEach(d=>{if(!S.links.some(l=>l.id==='deal_'+d.id))S.links.push({id:'deal_'+d.id,name:d.name,want:[d.com],real:1,deal:1})});return L}
async function network(){const P=S.eco||(S.eco=ecoProfile(S)),npc=S.npc||(S.npc=npcVillages(S)),C=COMN[lang];let real=[],deals=[];if(!GUEST){try{real=(await api('neighbors',null,'&lat='+S.loc.lat+'&lon='+S.loc.lon)).list}catch(e){}deals=await syncDeals();dealNotify(deals.filter(d=>d.dir==='in'&&d.st==='pending').length)}
 const linked=id=>(S.links||[]).some(l=>l.id===id),need=count('market')+count('kom')>0;
 const row=(v,isReal)=>`<div class="nb"><div><b>${esc(v.name)}</b>${isReal?` <small>· ${esc(v.who)}</small> <button type="button" class="visb" data-visit="${v.id}" data-vn="${esc(v.name)}">👁 ${L2('Lihat','View')}</button>`:''}<br><small>${isReal?esc(v.loc)+' · '+t('nbRel.'+v.rel):(lang==='en'?'NPC village':'Kampung NPC')} · ${v.km} km${v.want?' · '+(lang==='en'?'wants ':'butuh ')+v.want.map(k=>COM_IC[k]+' '+C[k]).join(', '):''}</small></div><div>${linked(v.id)?`<b style="color:#2f8f6a">✓ ${lang==='en'?'Linked':'Terhubung'}</b>`:`<button class="bigbtn alt lk" data-id="${v.id}" data-real="${isReal?1:0}" ${need?'':'disabled'}>🤝 ${money(v.cost||30,true)}</button>`}</div></div>`;
 const tr=S._trade;modal(`<h2>🤝 ${lang==='en'?'Trade network':'Jaringan dagang'}</h2><p class="note">${lang==='en'?'Your signature products':'Produk khas kampungmu'}: ${[P.staple,P.crop,P.craft,...P.nat].map(k=>COM_IC[k]+' '+C[k]).join(' · ')}</p>`+
  (need?'':`<p class="err">${lang==='en'?'Build a market or a comms post first.':'Bangun pasar atau pos komunikasi dulu.'}</p>`)+(tr&&tr.items.length?`<p><b>${lang==='en'?'Last month sold':'Terjual bulan lalu'}:</b> ${tr.items.map(i=>COM_IC[i[0]]+' '+C[i[0]]+' ×'+i[1]).join(', ')} → <b>${money(tr.income,true)}</b></p>`:'')+
  `<h3>📜 ${L2('Perjanjian dagang dua arah','Two-way trade agreements')}</h3>`+(GUEST?`<p class="note">${L2('Masuk dengan akun untuk membuat perjanjian dengan pemain lain.','Log in to make agreements with other players.')}</p>`:(deals.length?deals.map(d=>`<div class="nb"><div><b>${esc(d.name)}</b> <small>· ${esc(d.who)}</small><br><small>${COM_IC[d.com]||'📦'} ${esc(C[d.com]||d.com)} · ${d.st==='active'?L2('aktif: kedua kampung mendapat jalur dagang','active: both settlements gain a trade link'):d.dir==='in'?L2('menawarkan perjanjian kepadamu','offers you an agreement'):L2('menunggu jawaban','awaiting reply')}</small></div><div>${d.st==='pending'&&d.dir==='in'?`<button class="bigbtn dl" data-id="${d.id}" data-a="1">✓ ${L2('Terima','Accept')}</button> <button class="bigbtn alt dl" data-id="${d.id}" data-a="0">${L2('Tolak','Decline')}</button>`:`<button class="bigbtn alt dl" data-id="${d.id}" data-e="1">${d.st==='active'?L2('Akhiri','End'):L2('Batalkan','Cancel')}</button>`}</div></div>`).join(''):`<p class="note">${L2('Belum ada perjanjian. Usulkan kepada tetangga nyata di bawah: bila diterima, kedua kampung sama-sama mendapat jalur dagang dan pemasukan.','No agreements yet. Propose one to a real neighbour below: if accepted, both settlements gain a trade link and income.')}</p>`))+
  `<h3>${lang==='en'?'Real neighbours':'Tetangga nyata (pemain)'}</h3>`+(real.length?real.map(v=>row(Object.assign({cost:25},v),1).replace('</div></div>',(deals.some(d=>d.pid===v.id)?'':` <button class="bigbtn alt pr" data-id="${v.id}">📜 ${L2('Usulkan perjanjian','Propose deal')}</button>`)+'</div></div>')).join(''):`<p class="note">${t('nbNone')}</p>`)+`<h3>${lang==='en'?'Nearby villages':'Kampung sekitar'}</h3>`+npc.map(v=>row(v,0)).join(''));
 document.querySelectorAll('.pr').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('deal_offer',{to:b.dataset.id,com:P.crop||P.staple});toast(L2('📜 Usulan perjanjian terkirim.','📜 Proposal sent.'))}catch(e){toast(L2('Gagal mengirim: ','Failed: ')+e.message)}network()});
 document.querySelectorAll('.dl').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('deal_reply',b.dataset.e?{id:b.dataset.id,end:1}:{id:b.dataset.id,accept:b.dataset.a==='1'});Snd.play('coin')}catch(e){toast(e.message)}await syncDeals();try{dealNotify((S._deals||[]).filter(d=>d.dir==='in'&&d.st==='pending').length)}catch(e){}after();network()});
 document.querySelectorAll('.lk').forEach(b=>b.onclick=()=>{const isR=b.dataset.real==='1',v=isR?real.find(q=>q.id===b.dataset.id):npc.find(q=>q.id===b.dataset.id),c=v.cost||25;if(S.res.coin<c){toast(t('noMoney'));return}S.res.coin-=c;S.links.push({id:v.id,name:v.name,want:v.want||[],real:isR?1:0});Snd.play('coin');S.coh+=1;after();network()})}

