const LOANS=[33,67,133];
function loanMonth(){const L=S.loan;if(!L)return;const p=Math.min(L.inst,L.left);if(S.res.coin>=p){S.res.coin-=p;L.left=+(L.left-p).toFixed(2);L.n--;L.late=0}else{L.late=(L.late||0)+1;S.happy-=2;advise(L2('⚠️ Cicilan Bank Desa tertunggak. Kepuasan warga turun.','⚠️ Village Bank installment is overdue. Satisfaction drops.'),'eco')}
 if(L.left<=.01){S.loan=null;advise(L2('✅ Pinjaman Bank Desa lunas.','✅ Village Bank loan fully repaid.'),'eco')}}
function bank(){const L=S.loan;let h=`<h2>🏦 Bank Desa</h2>`;
 if(L)h+=`<p>${L2('Sisa pinjaman','Remaining loan')}: <b>${money(L.left,true)}</b><br>${L2('Cicilan','Installment')}: ${money(L.inst,true)} / ${L2('bulan','month')} · ${L.n} ${L2('bulan lagi','months left')}${L.late?' · ⚠️ '+L2('menunggak','overdue')+' '+L.late:''}</p><button class="bigbtn gold" id="bkPay" style="width:100%">${L2('Lunasi sekarang','Repay now')} · ${money(L.left,true)}</button>`;
 else h+=`<p>${L2('Pinjaman lunak untuk kampung yang kehabisan kas. Bunga 6% (total), dicicil otomatis 24 bulan dari kas. Hanya satu pinjaman aktif; cicilan tertunggak menurunkan kepuasan warga.','Soft loan for settlements short of funds. 6% total interest, repaid automatically over 24 months. One active loan at a time; overdue installments lower satisfaction.')}</p><div class="row">`+LOANS.map((a,i)=>`<button class="bigbtn alt bkL" data-a="${a}" ${i===2&&S.era<3?'disabled title="Era ≥ 3"':''}>${money(a,true)}</button>`).join('')+`</div>`;
 modal(h+'<div class="err" id="bkErr"></div>');
 document.querySelectorAll('.bkL').forEach(b=>b.onclick=()=>{const a=+b.dataset.a;if(S.loan)return;S.res.coin+=a;S.loan={amt:a,left:+(a*1.06).toFixed(2),inst:+(a*1.06/24).toFixed(2),n:24,late:0};S.loanTot=(S.loanTot||0)+a;Snd.play('coin');toast('🏦 +'+money(a,true));updHUD();dirty=true;bank()});
 const pb=$('bkPay');if(pb)pb.onclick=()=>{if(S.res.coin<S.loan.left){$('bkErr').textContent=t('noMoney');Snd.play('err');return}S.res.coin-=S.loan.left;S.loan=null;Snd.play('coin');updHUD();dirty=true;bank()}}
/* ---------- pembangunan berjalan per jam permainan; makin banyak tukang makin cepat ---------- */
const BUILD_RATE=4,CREW={};   // 1 regu (2 tukang) = 2 hari-kerja per jam permainan
function freeWorkers(){let jobs=0;built().forEach(b=>{jobs+=BT[b.t].jobs||0});return Math.max(2,S.kk*2-Math.floor(jobs*.6))+(S.hire||0)}
const wxBuild=()=>S.wx==='badai'||S.wx==='salju'?.3:S.wx==='hujan'?.8:1;
let _bsT=0;
function buildStep(dh){if(!S||!dh)return;const sites=S.b.filter(b=>b.bt>0);for(const k in CREW)delete CREW[k];if(!sites.length)return;
 let free=freeWorkers();const wx=wxBuild();const per=Math.max(2,Math.floor(free/sites.length/2)*2);
 for(const b of sites){const crew=Math.min(free,per,8);if(crew<2)break;free-=crew;CREW[b.id]=crew;if(!wx)continue;const T=BT[b.t].days||1,p0=Math.floor((1-b.bt/T)*100);
  b.bt=Math.max(0,+(b.bt-dh*BUILD_RATE*(+CFG.buildMul||1)*wx*crew/2).toFixed(4));
  if(b.bt<=0){delete b.bt;R3.delB(b.id);R3.addB(b);Snd.play('build');toast('✅ '+tlN(b.t)+(lang==='en'?' completed':' selesai dibangun'));if(b.t==='house')R3.villagers();after();infoRefresh()}
  else if(Math.floor((1-b.bt/T)*100)!==p0)R3.progress(b)}
 _bsT+=dh;if(_bsT>=.5){_bsT=0;infoRefresh()}}
function hireCrew(n){const cur=S.hire||0;if(n>0&&S.res.coin<2){toast(t('noMoney'));Snd.play('err');return}S.hire=Math.max(0,Math.min(40,cur+n));Snd.play(n>0?'coin':'click');toast(n>0?L2('👷 4 tukang sewaan mulai bekerja','👷 4 hired builders started'):L2('👷 4 tukang sewaan diberhentikan','👷 4 hired builders dismissed'));dirty=true;updHUD();infoRefresh()}
