const SELLP={wood:.15,stone:.08,iron:.3,food:.2};
function sellMat(){const nm={wood:[L2('Kayu','Timber'),'🪵'],stone:[L2('Batu','Stone'),'🪨'],iron:[L2('Besi','Iron'),'⛓️'],food:[L2('Pangan','Food'),'🌾']};const keep=k=>k==='food'?Math.ceil(S.kk*2+5):0,av=k=>Math.max(0,Math.floor((S.res[k]||0)-keep(k)));
 const row=k=>{const a=av(k);const qs=[10,Math.floor(a/2),a].filter((q,i,A)=>q>0&&q<=a&&A.indexOf(q)===i);return `<p style="margin:8px 0 4px"><b>${nm[k][1]} ${nm[k][0]}</b> · ${L2('punya','have')} <b>${Math.floor(S.res[k]||0)}</b>${k==='food'?` <small>(${L2('disisakan','kept')} ${keep(k)} ${L2('untuk makan warga','for households')})</small>`:''}</p><div class="row">`+(qs.length?qs.map(q=>`<button class="bigbtn alt sl" data-m="${k}" data-q="${q}">−${q} → +${money(q*SELLP[k],true)}</button>`).join(''):`<small>${L2('Tidak ada yang bisa dijual.','Nothing to sell.')}</small>`)+`</div>`};
 modal(`<h2>💱 ${L2('Jual bahan & hasil panen','Sell materials & produce')}</h2><p class="note">${L2('Pedagang membeli kira-kira separuh harga beli. Cocok untuk mengisi kas saat kosong.','Traders pay about half the purchase price. Handy to refill an empty treasury.')}</p>`+['wood','stone','iron','food'].map(row).join(''));
 document.querySelectorAll('.sl').forEach(b=>b.onclick=()=>{const k=b.dataset.m,q=Math.min(+b.dataset.q,av(k));if(q<=0)return;const c=+(q*SELLP[k]).toFixed(2);S.res[k]-=q;S.res.coin+=c;S.soldC=+((S.soldC||0)+c).toFixed(2);Snd.play('coin');toast('💱 +'+money(c,true));updHUD();dirty=true;sellMat()})}
function buyWood(){const nm={wood:L2('Kayu','Timber'),stone:L2('Batu','Stone'),iron:L2('Besi','Iron')};
 modal(`<h2>🧱 ${L2('Beli bahan bangunan','Buy building materials')}</h2><p class="note">${L2('Dari pedagang, penggergajian, dan toko bangunan terdekat. Membabat hutan (kayu) dan tambang batu tetap lebih murah.','From the nearest sawmill and building supplier. Clearing forest (timber) and a quarry (stone) are cheaper.')}</p>`+
 Object.keys(MAT_PACKS).map(m=>`<p style="margin:8px 0 4px"><b>${MAT_IC[m]} ${nm[m]}</b> · ${L2('punya','have')} <b id="bw_${m}">${Math.floor(S.res[m]||0)}</b></p><div class="row">`+MAT_PACKS[m].map(([q,c],i)=>`<button class="bigbtn alt bw" data-m="${m}" data-i="${i}">+${q} · ${money(c,true)}</button>`).join('')+`</div>`).join('')+`<div class="err" id="bwErr"></div>`);
 document.querySelectorAll('.bw').forEach(b=>b.onclick=()=>{const m=b.dataset.m,[q,c]=MAT_PACKS[m][+b.dataset.i];if(S.res.coin<c){$('bwErr').textContent=t('noMoney');Snd.play('err');return}S.res.coin-=c;S.res[m]=(S.res[m]||0)+q;if(m==='wood')S.woodBuy=(S.woodBuy||0)+q;Snd.play('coin');$('bw_'+m).textContent=Math.floor(S.res[m]);updHUD();dirty=true})}

