function depNear(b,types){const out=[];for(let dy=-1;dy<=b.h;dy++)for(let dx=-1;dx<=b.w;dx++){const d=depAt(b.x+dx,b.y+dy);if(d&&d.q>0&&types.includes(d.t))out.push(d)}return out}
function depOK(k,x,y){const ty=depTypes(k);if(!ty||k==='tambang')return true;const T=BT[k];for(let dy=0;dy<T.h;dy++)for(let dx=0;dx<T.w;dx++){const d=depAt(x+dx,y+dy);if(d&&d.q>0&&ty.includes(d.t))return true}return false}
