function mineMonth(staff){const o={stone:0,iron:0,coin:0};built().forEach(b=>{const ty=depTypes(b.t);if(!ty)return;const ds=depNear(b,ty);if(!ds.length){return}
  const d0=ds[0],Y=MYLD[d0.t]||{},f=staff*(b.t==='tambang'?LVM(b):1);let take=Math.round(12*f);
  Object.keys(Y).forEach(k=>o[k]+=Math.round(Y[k]*f));ds.forEach(d=>{const u=Math.min(d.q,take);d.q-=u;take-=u});
  if(ds.every(d=>d.q<=0)&&!b.hab){b.hab=1;advise(L2('Cadangan '+MIN[d0.t].n[0].toLowerCase()+' di dekat '+tlN(b.t)+' sudah habis. Bongkar lalu tanam pohon (reklamasi).','The '+MIN[d0.t].n[1].toLowerCase()+' reserve near the '+tlN(b.t)+' is exhausted. Demolish it and plant trees (reclamation).'),'eng');try{R3.deposits()}catch(e){}}});return o}
