/* ---------- ukuran kota berkelanjutan & cerdas ---------- */
const CLEAN_PW=['surya','pltmh','pltb','kincir','plts','ladangangin'];
function pwOf(t){return built().filter(b=>b.t===t&&!b.dmg).length*(BT[t].pw||0)}
/** porsi listrik bersih (0–1) dari seluruh pasokan; PLTSa dihitung setengah bersih */
function cleanShare(){let tot=0,cl=0;built().forEach(b=>{const p=BT[b.t].pw;if(!p||b.dmg)return;tot+=p;if(CLEAN_PW.includes(b.t))cl+=p;else if(b.t==='pltsa')cl+=p/2});return tot?cl/tot:0}
function bandaraLv(){return built().filter(b=>b.t==='bandara').reduce((a,b)=>Math.max(a,Math.min(3,b.lv||1)),0)}
function komLv(){return built().filter(b=>b.t==='kom').reduce((a,b)=>Math.max(a,Math.min(3,b.lv||1)),0)}
const msay=m=>{toast(m);try{Snd.play('err')}catch(e){}};
const cl01=v=>Math.max(0,Math.min(1,v));
/** indeks kota cerdas 0–100 per dimensi (Giffinger dkk., 2007) */
function smartIdx(){const C=S.city||{},kk=Math.max(1,S.kk),c=count;
 const eco=cl01(.25*Math.min(1,c('ecom'))+.15*Math.min(1,c('ekspedisi'))+.2*Math.min(1,c('dagang'))+.15*Math.min(1,c('cbd'))+.1*Math.min(1,c('datacenter'))+.15*(C.emp==null?.5:C.emp));
 const mob=cl01(.2*Math.min(1,c('mrt'))+.15*Math.min(1,c('lrt')+c('monorel'))+.15*Math.min(1,c('kcj'))+.1*Math.min(1,c('spklu')/5)+.1*Math.min(1,c('brt')+c('stasiun'))+.1*Math.min(1,c('vertiport'))+.2*(1-(C.traffic||0)/100));
 const env=cl01(.35*cleanShare()+.2*(C.garb==null?1:C.garb)+.2*(1-(C.pol||0)/100)+.1*Math.min(1,c('tpst')+c('pltsa'))+.15*Math.min(1,(c('tamkot')+c('menarahuni')+c('alun'))/4));
 const ppl=cl01(.35*(C.edu==null?.5:Math.min(1,C.edu))+.15*Math.min(1,c('kampus'))+.15*Math.min(1,risetLv()/3)+.2*komLv()/3+.15*Math.min(1,c('satelit')+c('datacenter')));
 const liv=cl01(.3*(C.health==null?.5:Math.min(1,C.health))+.25*((C.aman==null?50:C.aman)/100)+.2*Math.min(1,(C.amen||0)/80)+.15*(S.happy/100)+.1*Math.min(1,c('labkes')));
 const gov=cl01(.3*Math.min(1,c('iot'))+.2*Math.min(1,c('cmd112'))+.15*Math.min(1,c('balkot'))+.15*Math.min(1,c('cctv')/5)+.2*Math.min(1,(C.gov||0)/80));
 const D={eco,mob,env,ppl,liv,gov};Object.keys(D).forEach(k=>D[k]=Math.round(D[k]*100));D.tot=Math.round((D.eco+D.mob+D.env+D.ppl+D.liv+D.gov)/6);return D}
/** warga cerdas (literasi digital & pendidikan) memperbesar hasil ekonomi digital */
const wargaCerdas=()=>smartIdx().ppl;
function metroKonek(){return count('lrt')*5+count('monorel')*4+count('mrt')*9+count('kcj')*12+count('vertiport')*6+count('satelit')*5}
/** pendapatan bulanan metropolitan (kas) */
function metroInc(staff){if(S.era<5)return 0;const kl=komLv(),sat=count('satelit')?1:0,exp=count('ekspedisi')?1.5:1,links=(S.links||[]).length;
 const eco=Math.min(3,count('ecom'))*S.kk*.12*(1+kl/3+sat*.3)*exp;
 const v=eco+count('ekspedisi')*10+count('dagang')*(40+8*Math.min(40,links)+10*(count('pelabuhan')+count('kargo')))+count('cbd')*30+count('datacenter')*25*(1+sat)+count('satelit')*15+count('kcj')*20+count('mrt')*8+(count('lrt')+count('monorel'))*5+count('vertiport')*12+count('plts')*4+count('ladangangin')*5+count('bsampah')*1+count('tpst')*3;
 return Math.round(v*staff*(1+wargaCerdas()/300))}

/* ---------- ekspedisi & perdagangan antarbenua ---------- */
const BENUA=[['asia','🌏','Asia','Asia',120,1],['oseania','🦘','Oseania','Oceania',220,2],['eropa','🏰','Eropa','Europe',320,3],['afrika','🦁','Afrika','Africa',300,3],['amerika','🗽','Amerika','Americas',400,4]];
function expedOK(mode,dest){const far=dest!=='asia';if(mode==='air'){const lv=bandaraLv();if(!lv)return L2('Perlu bandara.','Needs an airport.');if(far&&lv<3)return L2('Penerbangan antarbenua perlu bandara internasional (tingkat 3).','Intercontinental flights need an international airport (level 3).');return ''}
 if(!count('pelabuhan'))return L2('Perlu pelabuhan.','Needs a port.');return ''}
function expedLaunch(dest,mode){const B=BENUA.find(x=>x[0]===dest);if(!B)return;const why=expedOK(mode,dest);if(why){msay(why);return}
 if(!count('ekspedisi')){msay(L2('Bangun Pusat ekspedisi & logistik dulu.','Build a courier & logistics hub first.'));return}S.expd=S.expd||[];if(S.expd.length>=3){msay(L2('Maksimal 3 ekspedisi berjalan.','At most 3 expeditions at a time.'));return}
 const cost=Math.round(B[4]*(mode==='air'?1.3:1));if(S.res.coin<cost){msay(t('noMoney'));return}S.res.coin-=cost;
 const months=mode==='air'?1+B[5]:3+B[5]*2;S.expd.push({d:dest,m:mode,c:cost,due:S.t+months});Snd.play('coin');toast((mode==='air'?'✈️ ':'🚢 ')+L2('Ekspedisi dagang ke ','Trade expedition to ')+(lang==='en'?B[3]:B[2])+L2(' berangkat · kembali ±'+months+' bulan',' departed · back in ~'+months+' months'));save()}
function expedTick(){if(!S.expd||!S.expd.length)return;S.expd=S.expd.filter(e=>{if(S.t<e.due)return true;const B=BENUA.find(x=>x[0]===e.d)||BENUA[0];const ok=Math.random()<.9;
  const mul=(1.35+Math.random()*.55)*(1+Math.min(40,(S.links||[]).length)*.02)*(count('kargo')&&e.m==='air'?1.1:1)*(count('dagang')?1.15:1)*(1+wargaCerdas()/400);
  const gain=ok?Math.round(e.c*mul):Math.round(e.c*.4);S.res.coin+=gain;S.expdC=(S.expdC||0)+gain;S.expDone=S.expDone||{};if(ok)S.expDone[e.d+'_'+e.m]=(S.expDone[e.d+'_'+e.m]||0)+1;
  advise((ok?'📦 ':'⚠️ ')+L2('Ekspedisi '+(e.m==='air'?'udara':'laut')+' dari '+B[2]+(ok?' sukses: +':' terkendala cuaca, sebagian kembali: +')+money(gain),(e.m==='air'?'Air':'Sea')+' expedition from '+B[3]+(ok?' succeeded: +':' hit bad weather, partial return: +')+money(gain)),'eco');return false})}
const expBenua=()=>new Set(Object.keys(S.expDone||{}).map(k=>k.split('_')[0])).size;

/* ---------- krisis kota: sampah, polusi, kriminalitas, kebakaran, wabah & pandemi ---------- */
const CRISIS={sampah:['🗑️','Krisis sampah','Waste crisis','Sampah meluap ke jalan dan sungai.','Rubbish spills onto streets and rivers.','Tambah TPS, TPST, bank sampah, daur ulang atau PLTSa sampai pengelolaan sampah ≥ 95%.','Add depots, integrated waste centres, waste banks, recycling or waste-to-energy until waste ≥ 95%.'],
 polusi:['🌫️','Kabut polusi','Smog','Udara kota tercemar; warga batuk-batuk.','City air is polluted; residents cough.','Kurangi PLTU & industri dekat hunian, tambah taman, SPKLU, transportasi rel & energi bersih sampai polusi < 35.','Cut coal power & industry near homes, add parks, EV chargers, rail and clean power until pollution < 35.'],
 kriminal:['🚔','Gelombang kriminalitas','Crime wave','Pencurian & begal meningkat.','Theft and robbery rise.','Tambah pos polisi, CCTV pintar, pusat IoT & lapangan kerja sampai kriminalitas < 30.','Add police posts, smart CCTV, an IoT centre & jobs until crime < 30.'],
 kebakaran:['🔥','Kebakaran besar','Major fire','Api merambat ke beberapa bangunan.','Fire spreads across several buildings.','Bangun damkar dekat hunian & pusat komando 112 sampai jangkauan pemadam ≥ 85%.','Build fire stations near homes & a 112 command centre until fire coverage ≥ 85%.'],
 wabah:['🦠','Wabah penyakit menular','Infectious outbreak','Penyakit menular menyebar; warga jatuh sakit.','An infectious disease spreads; residents fall ill.','Perbaiki air bersih & sanitasi, tambah klinik, RS & lab kesehatan sampai layanan kesehatan ≥ 90%.','Improve water & sanitation, add clinics, hospitals & a health lab until health ≥ 90%.'],
 pandemi:['😷','Pandemi','Pandemic','Penyakit menular global sampai ke kota; bandara jadi pintu masuk.','A global disease reaches the city via the airport.','Siapkan lab kesehatan & vaksin, RS rujukan penyakit menular, dan layanan kesehatan ≥ 100%.','Prepare a health lab & vaccines, an infectious-disease hospital, and health ≥ 100%.']};
function crisisSolved(k,C){if(k==='sampah')return C.garb>=.95;if(k==='polusi')return C.pol<35;if(k==='kriminal')return C.crime<30;if(k==='kebakaran')return (C.fireCov||0)>=.85;if(k==='wabah')return C.health>=.9&&C.water>=.8;if(k==='pandemi')return C.health>=1&&count('labkes')>=1&&count('rsinf')>=1;return true}
/** dipanggil dari citySim tiap bulan; mengembalikan pesan bila ada */
function metroCrisis(C,Bs){if(S.era<5)return null;const dk=DIS();
 if(S.crisis){const k=S.crisis.k,Q=CRISIS[k];if(crisisSolved(k,C)){const pts=k==='pandemi'?30:15,coin=60+20*S.era;S.crs=S.crs||{};S.crs[k]=(S.crs[k]||0)+1;S.res.coin+=coin;S.crisis=null;Snd.play('mission');return '✅ '+L2(Q[1]+' teratasi! +'+pts+' poin, +'+money(coin),Q[2]+' resolved! +'+pts+' points, +'+money(coin))}
  S.happy=Math.max(0,S.happy-3);if((k==='wabah'||k==='pandemi')&&S.kk>20){const loss=Math.max(1,Math.round(S.kk*(k==='pandemi'?.015:.006)*(1-Math.min(1,C.health))));S.kk-=loss}
  if(k==='kebakaran'&&Math.random()<.3){const cand=Bs.filter(b=>!b.dmg&&!['tree','field','kebun','pond'].includes(b.t));const b=cand[Math.floor(Math.random()*cand.length)];if(b&&!near(b.x,b.y,'damkar',12))b.dmg=4}
  return (S.t-(S.crisis.adv||0))>=3?(S.crisis.adv=S.t,Q[0]+' '+L2(Q[1]+' masih berlangsung. ',Q[2]+' still ongoing. ')+L2(Q[5],Q[6])):null}
 if(Math.random()>.10*dk)return null;const cand=[];if(C.garb<.8)cand.push('sampah');if(C.pol>55)cand.push('polusi');if(C.crime>50)cand.push('kriminal');if((C.fireCov||0)<.6&&S.era>=5)cand.push('kebakaran');
 if(C.health<.6||C.sew<.6||C.water<.7)cand.push('wabah');if(S.era>=7&&S.kk>=500&&bandaraLv()>=2&&Math.random()<.25)cand.push('pandemi');if(!cand.length)return null;
 const k=cand[Math.floor(Math.random()*cand.length)],Q=CRISIS[k];S.crisis={k,since:S.t,adv:S.t};Snd.play('err');
 if(k==='kebakaran'){let n=0;Bs.filter(b=>!b.dmg&&!['tree','field','kebun','pond'].includes(b.t)&&!near(b.x,b.y,'damkar',12)).slice(0,3).forEach(b=>{b.dmg=4;n++});if(count('cmd112'))n=Math.ceil(n/2)}
 return Q[0]+' '+L2(Q[1]+'! '+Q[3]+' ',Q[2]+'! '+Q[4]+' ')+L2(Q[5],Q[6])}

/* ---------- tujuan berkelanjutan & tantangan metropolitan (berpoin) ----------
   [id, ikon, judul id, judul en, poin, hadiah kas, era tampil, syarat] — syarat struktural yang sama dicek ulang server (api/index.php METRO_CH). */
