  if(B(-9,-8,114.4,115.75))return {s:['bali'],r:'Bali'};
  if(B(-9,-5.8,105,108.8))return {s:['panggung','jawa'],r:'Sunda / Betawi'};
  if(B(-9,-5.8,108.8,114.7))return {s:['jawa','joglo'],r:'Jawa'};
