 <div class="row" style="gap:8px;flex-wrap:wrap;margin:6px 0"><div class="kv"><span>${L2('Mahasiswa aktif','Active students')}</span><b>${n}</b></div><div class="kv"><span>${L2('Main 7 hari terakhir','Played in last 7 days')}</span><b>${act}</b></div><div class="kv"><span>${L2('Rata-rata skor terbaik','Average best score')}</span><b>${avg}</b></div>${R.some(r=>r.tantangan)?`<div class="kv"><span>🎯 ${L2('Tantangan tercapai','Challenge met')}</span><b>${ch}/${n}</b></div>`:''}</div>
