if(/^(127\.0\.0\.1|localhost)$/.test(location.hostname)){window.__R3=R3;window.__BA={h:(x,z)=>R3.hAt(x,z),setAva:a=>{draft.char.ava=a;renderAvEditor()},rebuild:()=>{R3.world()},weather:w=>{S.wx=w;R3.weather(w,seasonOf(calM()));R3.daylight(S.clk.h/24)},ui:()=>{updHUD();renderMissions()},style:v=>{curStyle=v},cam:(x,y,z,tx,ty,tz)=>{const o=R3.cam();o.controls.target.set(tx,ty,tz);o.camera.position.set(x,y,z)},look:(x,z,d)=>R3.look(x,z,d),lp:()=>{const v=R3.leaderPos();return v?[v.x,v.y,v.z]:null},real:()=>REAL.ok,dbg:()=>R3.dbg(),ppl:()=>R3.peopleDbg(),relife:()=>R3.lifeRebuild(),fs:(x,z)=>R3.fsDbg(x,z),occAt:(x,y)=>{const id=occ&&occ[y]?occ[y][x]:0,b=id&&S.b.find(q=>q.id===id);return b?b.t:(isRoad(x,y)?'road':L(x,y))},state:()=>S,tick,day:()=>{S.clk.d++;dayTick()},build:h=>buildStep(h),actUI:(k,x,y)=>{tool=k;act(x,y)},tele:()=>teleSum(),konek:()=>konek(),brSpan:(x,y)=>brSpan(x,y),sellMat:()=>sellMat(),net:()=>netLv(),umkm:()=>umkmBoost(),musKey:l=>Snd.musKey(l),musName:()=>Snd.musName(),vern:l=>vernac(l),styles:()=>allowedStyles(),mine:f=>mineMonth(f||1),geo:l=>geoMin(l),gdep:(sd,l)=>genDep(sd,l),placeOK:(k,x,y)=>{const o=tool;tool=k;const r=placeOK(x,y);tool=o;return r},act:(k,x,y)=>{tool=k;act(x,y,true)},BT,v52:()=>({smart:smartIdx(),clean:cleanShare(),pts:mchPts(),inc:metroInc(1),mch:S.mch,crisis:S.crisis}),metroUI:t=>metroUI(t),city:()=>citySim(),exped:(d,m)=>expedLaunch(d,m),expedTick:()=>expedTick()};}

/* ================= v50r: hemat sumber daya =================
   1) satu tab aktif: tab lama berhenti & melepas memori bila Babat Alas dibuka di tab lain;
   2) tab yang tersembunyi > 2 menit menyimpan, melepas dunia 3D, lalu dimuat ulang saat dibuka lagi;
   3) peringatan bila peramban menggambar tanpa akselerasi grafis. */
(()=>{const ID=Math.random().toString(36).slice(2);let halted=false,hidT=0,warned=false;
 const bc=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('babat-alas-tab'):null;
 const ov=(html)=>{let o=document.getElementById('baHalt');if(!o){o=document.createElement('div');o.id='baHalt';document.body.appendChild(o)}o.innerHTML=`<div class="box">${html}</div>`;return o};
 async function halt(kind){if(halted)return;halted=true;const wasGame=!!S;
  if(kind==='tab'){const o=ov(`<h2>🪓 ${L2('Babat Alas dibuka di tab lain','Babat Alas is open in another tab')}</h2><p>${L2('Tab ini dihentikan dan memorinya dilepas agar perangkat tidak berat.','This tab was stopped and its memory released so your device stays light.')} <span id="baSv">${wasGame?L2('Menyimpan permainan…','Saving your game…'):''}</span></p><button class="bigbtn" id="baHere" ${wasGame?'disabled':''}>▶ ${L2('Lanjutkan di tab ini','Continue in this tab')}</button>`);o.querySelector('#baHere').onclick=()=>resume(wasGame)}
  else ov(`<h2>⏸ ${L2('Permainan dijeda','Game paused')}</h2><p>${L2('Tab ini lama tersembunyi, jadi dunia 3D dilepas untuk menghemat memori. Permainan disimpan dan dimuat kembali saat tab dibuka.','This tab was hidden for a while, so the 3D world was released to save memory. Your game is saved and reloads when you return.')}</p>`);
  try{clearInterval(loopT)}catch(e){}
  if(wasGame){for(let i=0;i<50&&saving;i++)await new Promise(r=>setTimeout(r,100));try{dirty=true;await save(true)}catch(e){}}
  try{Snd.close()}catch(e){}try{R3.release&&R3.release()}catch(e){}try{document.querySelectorAll('canvas').forEach(c=>{c.width=c.height=1})}catch(e){}
  const sv=document.getElementById('baSv');if(sv)sv.textContent=L2('Permainan sudah disimpan.','Your game has been saved.');const bh=document.getElementById('baHere');if(bh)bh.disabled=false;
  if(kind!=='tab'&&!document.hidden)resume(wasGame)}
 function resume(cont){try{if(cont)sessionStorage.setItem('baAutoCont','1')}catch(e){}location.reload()}
 if(bc){bc.onmessage=e=>{const d=e.data||{};if(d.t==='hello'&&d.id!==ID&&!LEFT)halt('tab')};bc.postMessage({t:'hello',id:ID})}
 document.addEventListener('visibilitychange',()=>{clearTimeout(hidT);if(document.hidden){if(S&&!halted)hidT=setTimeout(()=>{if(document.hidden&&S)halt('hidden')},120000)}else if(halted&&document.getElementById('baHalt')&&!document.getElementById('baHere'))resume(true)});
 /* lanjut otomatis ke permainan setelah dimuat ulang oleh tombol di atas */
 try{if(sessionStorage.getItem('baAutoCont')){sessionStorage.removeItem('baAutoCont');let n=0;const iv=setInterval(()=>{const b=document.getElementById('hubCont');if(b&&b.offsetParent&&!b.classList.contains('hidden')){clearInterval(iv);b.click()}else if(++n>60)clearInterval(iv)},250)}}catch(e){}
 /* akselerasi grafis mati → mode Hemat + pesan sekali */
 const w=setInterval(()=>{if(!S||warned)return;warned=true;clearInterval(w);if(SET.q==='auto'&&gpuTier()==='eco'){setTimeout(()=>toast(L2('⚠️ Akselerasi grafis peramban tampaknya mati — gim memakai mode Hemat. Nyalakan “Gunakan akselerasi grafis/hardware acceleration” di pengaturan Chrome/Edge agar lancar.','⚠️ Browser graphics acceleration seems off — using Eco mode. Turn on “Use hardware acceleration” in Chrome/Edge settings for smooth play.')),4000)}},2000);
 window.__BAtab={halt,gpu:()=>({tier:gpuTier(),r:gpuTier.r,q:qEff()})};
})();

/* ================= v51: LENCANA & WILAYAH BERSAMA =================
   Lencana dinilai SERVER saat permainan disimpan (dari bangunan & indikator); di sini hanya tampilan & perkiraan progres. */
const BADGES=[
 ['hijau','🌳','Kampung Hijau','Green Kampung','RTH ≥ 30% (indikator rapor) dan ≥ 50 KK.','Green space ≥ 30% (report indicator) and ≥ 50 households.'],
 ['airbersih','💧','Air Bersih untuk Semua','Clean Water for All','≥ 95% hunian berjarak ≤ 5 petak dari sumur; ≥ 20 KK dan ≥ 8 hunian.','≥ 95% of dwellings within 5 tiles of a well; ≥ 20 households, ≥ 8 dwellings.'],
 ['pejalan','🚶','Kampung Pejalan Kaki','Walkable Kampung','≥ 90% hunian menempel jalan, ≥ 80% hunian ≤ 10 petak dari pasar/ruko dan ≤ 10 petak dari sekolah/PAUD; ≥ 30 KK.','≥ 90% of dwellings on a road, ≥ 80% within 10 tiles of a market/shop and of a school; ≥ 30 households.'],
 ['anak','🧒','Kampung Ramah Anak','Child-Friendly Kampung','Ada PAUD/sekolah dan klinik/puskesmas keliling/RS; ≥ 80% hunian ≤ 8 petak dari taman/taman bermain/lapangan; ≥ 40 KK.','A preschool/school and a clinic; ≥ 80% of dwellings within 8 tiles of a park/playground/field; ≥ 40 households.'],
 ['tanpakumuh','🏘️','Kampung Tanpa Kumuh','Slum-Free Kampung','Semua hunian menempel jalan, tidak di bantaran sungai, rumah ≤ 5 petak dari sumur; ada TPS/TPA/daur ulang; ≥ 40 KK.','Every dwelling on a road, none on the riverbank, houses within 5 tiles of a well; a waste facility; ≥ 40 households.'],
 ['lokal','🛖','Arsitektur Lokal','Local Architecture','≥ 80% rumah bergaya tradisional setempat; ≥ 15 rumah.','≥ 80% of houses in the local traditional style; ≥ 15 houses.'],
 ['pangan','🌾','Pangan Mandiri','Food Self-Sufficient','Produksi pangan (ladang, kolam, kandang, peternakan, pemburu) ≥ 2 × jumlah KK; ≥ 30 KK.','Food production ≥ 2 × households; ≥ 30 households.'],
 ['tangguh','🛡️','Tangguh Bencana','Disaster-Resilient','Ada saluran drainase, kolam retensi, dan damkar; tidak ada hunian di bantaran; ≥ 70 KK.','Drainage, retention pond and fire station; no dwellings on the riverbank; ≥ 70 households.'],
 ['rukun','🤝','Kampung Rukun','Harmonious Kampung','Kepuasan ≥ 75, ada balai dan tempat ibadah; ≥ 50 KK.','Satisfaction ≥ 75, a hall and a place of worship; ≥ 50 households.'],
 ['tersambung','🛣️','Jejaring Tersambung','Connected Network','Indikator jejaring ≥ 90; ≥ 30 KK.','Network indicator ≥ 90; ≥ 30 households.'],
 ['melayani','🏛️','Kota Melayani','Serving City','Layanan kota ≥ 85 (era Kota Kecil ke atas).','City services ≥ 85 (era 4 and above).'],
 ['sungai','🐟','Penjaga Sungai','River Keeper','Pencemaran kampungmu ≤ 10, kesehatan sungai wilayah ≥ 80, wilayah ≥ 2 kampung; ≥ 50 KK.','Your pollution ≤ 10, regional river health ≥ 80, region ≥ 2 kampungs; ≥ 50 households.']];
function badgeProg(k){try{const bs=S.b,kk=S.kk,I=S._ind||{},cnt=(...t)=>bs.filter(b=>t.includes(b.t)).length,dw=bs.filter(b=>['house','perum','apartemen'].includes(b.t)),nd=dw.length,pct=x=>Math.round(x*100)+'%';
 const near=(h,ts,r)=>{const hx=h.x+(h.w-1)/2,hy=h.y+(h.h-1)/2;return bs.some(b=>ts.includes(b.t)&&Math.abs(b.x+(b.w-1)/2-hx)<=r+(b.w-1)/2&&Math.abs(b.y+(b.h-1)/2-hy)<=r+(b.h-1)/2)};
 const ring=(h,l)=>{for(let y=h.y-1;y<=h.y+h.h;y++)for(let x=h.x-1;x<=h.x+h.w;x++)if(inside(x,y)&&S.land[y][x]===l)return true;return false};
 const sh=f=>nd?dw.filter(f).length/nd:0,KK=n=>`${kk}/${n} KK`;
 switch(k){case 'hijau':return `RTH ${I.rth??'–'}% · ${KK(50)}`;
  case 'airbersih':return `${pct(sh(h=>near(h,['well'],5)))} ${L2('hunian dekat sumur','dwellings near a well')} · ${KK(20)}`;
  case 'pejalan':return `${pct(sh(h=>ring(h,'P')))} ${L2('menempel jalan','on a road')} · ${pct(sh(h=>near(h,['market','pasmal','ruko'],10)))} ${L2('dekat pasar','near a market')} · ${pct(sh(h=>near(h,['paud','sekolah','smp','sma'],10)))} ${L2('dekat sekolah','near a school')}`;
  case 'anak':return `${L2('PAUD/sekolah','School')} ${cnt('paud','sekolah')} · ${L2('klinik','clinic')} ${cnt('klinik','puskesling','rs')} · ${pct(sh(h=>near(h,['taman','playground','tamkot','lapbola','alun'],8)))} ${L2('dekat taman','near a park')} · ${KK(40)}`;
  case 'tanpakumuh':return `${pct(sh(h=>ring(h,'P')&&!ring(h,'W')&&(h.t!=='house'||near(h,['well'],5))))} ${L2('hunian layak (perlu 100%)','decent dwellings (need 100%)')} · ${L2('pengelolaan sampah','waste facility')} ${cnt('tps','tpa','daurulang')} · ${KK(40)}`;
  case 'lokal':{const hs=bs.filter(b=>b.t==='house'),v=vernac(S.loc).s;return `${hs.length?pct(hs.filter(h=>v.includes(h.s)).length/hs.length):'0%'} ${L2('rumah bergaya','houses in')} ${v.join('/')} · ${hs.length}/15 ${L2('rumah','houses')}`}
  case 'pangan':{const p=cnt('field')*6+cnt('pond')*2+cnt('kandang')*3+cnt('peternakan')*5+cnt('pemburu')*3;return `${L2('produksi','production')} ${p} / ${kk*2} · ${KK(30)}`}
  case 'tangguh':return `${L2('saluran','drainage')} ${cnt('saluran')} · ${L2('retensi','retention')} ${cnt('retensi')} · ${L2('damkar','fire stn')} ${cnt('damkar')} · ${pct(sh(h=>!ring(h,'W')))} ${L2('hunian di luar bantaran','off the riverbank')} · ${KK(70)}`;
  case 'rukun':return `${L2('kepuasan','satisfaction')} ${I.k??'–'} · ${L2('balai','hall')} ${cnt('hall','baldes')} · ${L2('ibadah','worship')} ${cnt('worship')} · ${KK(50)}`;
  case 'tersambung':return `${L2('jejaring','network')} ${I.n??'–'} · ${KK(30)}`;
  case 'melayani':return `${L2('layanan kota','city services')} ${I.svc??'–'} · era ${S.era}/4`;
  case 'sungai':return `${L2('kesehatan sungai wilayah','regional river health')} ${S._river??'–'} · ${KK(50)}`}}catch(e){}return ''}
function badgeLine(){if(GUEST||S.scen)return '';const n=Object.keys(S._badges||{}).length;return `<div class="ms bline" style="cursor:pointer" id="msBadge"><i>🏅</i><span><b>${L2('Lencana','Badges')} ${n}/${BADGES.length}</b> · ${L2('ketuk untuk melihat syaratnya','tap to see the criteria')}${S._river!=null?` · 🌊 ${L2('sungai wilayah','regional river')} ${S._river}`:''}</span></div>`}
document.getElementById('missions').addEventListener('click',e=>{if(e.target.closest('#msBadge'))badgesUI()});
function badgesUI(){if(GUEST||S.scen){modal(`<h2>🏅 ${L2('Lencana','Badges')}</h2><p>${L2('Lencana hanya untuk permainan yang tersimpan di akun (bukan tamu atau skenario latihan).','Badges are only for games saved to an account (not guest or practice scenarios).')}</p>`);return}
 const got=S._badges||{},n=Object.keys(got).length;
 modal(`<h2>🏅 ${L2('Lencana kampung','Kampung badges')} · ${n}/${BADGES.length}</h2><p class="note">${L2('Dinilai server setiap kali permainan disimpan, dari bangunan dan indikator rapor. Lencana yang sudah didapat tetap tercatat dan muncul di rekap dosen. Angka di bawah hanya perkiraan sampai disimpan.','Assessed by the server on every save, from buildings and report indicators. Earned badges stay recorded and appear in the lecturer summary. Figures below are estimates until you save.')}</p>`+
  BADGES.map(([k,ic,ni,ne,di,de])=>{const at=got[k];return `<div class="nb" style="align-items:flex-start;${at?'':'opacity:.92'}"><div style="font-size:26px;line-height:1;margin-right:10px;filter:${at?'none':'grayscale(1) opacity(.55)'}">${ic}</div><div style="flex:1"><b>${lang==='en'?ne:ni}</b>${at?` <small style="color:#2f8f6a;font-weight:800">✓ ${new Date(at*1000).toLocaleDateString(lang==='en'?'en-GB':'id-ID')}</small>`:''}<br><small>${lang==='en'?de:di}</small><br><small style="color:var(--muted)">${at?'':'📊 '+esc(badgeProg(k))}</small></div></div>`}).join('')+
  `<div class="row" style="margin-top:10px"><button class="bigbtn alt" id="bdSave">💾 ${L2('Simpan & nilai sekarang','Save & assess now')}</button></div>`);
 const b=$('bdSave');if(b)b.onclick=async()=>{dirty=true;await save(true);badgesUI()}}
function baBadgesFromSave(j){S._badges=j.badges||{};if(j.river!=null)S._river=j.river;if(j.newBadges&&j.newBadges.length){const nm=j.newBadges.map(k=>{const B=BADGES.find(x=>x[0]===k);return B?B[1]+' '+(lang==='en'?B[3]:B[2]):k}).join(', ');advise('🏅 '+L2('Lencana baru: ','New badge: ')+nm+L2(' — tercatat di rekap dosen.',' — recorded for your lecturer.'),'elder');Snd.play('mission')}}

/* ---------- Wilayah bersama ---------- */
const RP_IC={jembatan:'🌉',terminal:'🚌',rs:'🏥',limbah:'♻️'},RES_N={coin:()=>L2('Kas','Cash'),wood:()=>L2('Kayu','Wood'),stone:()=>L2('Batu','Stone')};
const RP_FX=fx=>Object.entries(fx).map(([k,v])=>({n:L2('jejaring','network'),e:L2('ekonomi','economy'),c:L2('kenyamanan','comfort'),river:L2('kesehatan sungai','river health')}[k]+' +'+v)).join(', ');
function resTxt(r,v){return r==='coin'?money(v,true):Math.round(v)+' '+RES_N[r]().toLowerCase()}
async function regionUI(noSave){if(GUEST||S.scen){modal(`<h2>🗺️ ${L2('Wilayah bersama','Shared region')}</h2><p>${L2('Wilayah bersama hanya untuk permainan yang tersimpan di akun.','Shared regions are only for games saved to an account.')}</p>`);return}
 let j;try{if(!noSave){dirty=true;await save(true)}j=await api('region')}catch(e){toast(e.message==='no_save'?L2('Simpan permainan dulu.','Save your game first.'):t('errNet'));return}
 if(j.ver)saveVer=j.ver;S._river=j.river;const rv=j.river,rc=rv>=80?'#2f8f6a':rv>=50?'#e0a526':'#c0392b';
 const fx=j.fx||{},fxs=[fx.n?L2('jejaring','network')+' '+(fx.n>0?'+':'')+fx.n:'',fx.e?L2('ekonomi','economy')+' '+(fx.e>0?'+':'')+fx.e:'',fx.c?L2('kenyamanan','comfort')+' '+(fx.c>0?'+':'')+fx.c:''].filter(Boolean).join(' · ');
 modal(`<h2>🗺️ ${esc(j.label)}</h2><p class="note">${j.rid==='k:'?L2('Wilayahmu adalah kelasmu.','Your region is your class.'):L2('Wilayahmu: kampung-kampung dalam radius sekitar 25 km. Bergabung ke kelas lewat Profil untuk berwilayah bersama teman sekelas.','Your region: kampungs within about 25 km. Join a class via Profile to share a region with classmates.')} ${j.rank?L2('Peringkat wilayah','Region rank')+` <b>${j.rank}/${j.regions}</b>.`:''}</p>
  <h3 style="margin:10px 0 4px">🌊 ${L2('Sungai bersama','Shared river')}: <b style="color:${rc}">${rv}/100</b></h3><div class="pb" style="height:10px;border-radius:6px;background:rgba(0,0,0,.12);overflow:hidden"><i style="display:block;height:100%;width:${rv}%;background:${rc}"></i></div>
  <p class="note" style="margin:6px 0">${L2('Kesehatan sungai = 100 − 1,2 × rata-rata pencemaran semua kampung di wilayah (+25 bila pengolahan limbah terpadu selesai). Di bawah 50: kenyamanan semua anggota −6. Di atas 80: +3. Pencemaran kampungmu','River health = 100 − 1.2 × average pollution of all kampungs in the region (+25 once the shared waste plant is done). Below 50: everyone’s comfort −6. Above 80: +3. Your pollution')}: <b>${j.pol}</b> — ${L2('industri, PLTU, semen, smelter, tambang, galian, tobong, peternakan menambah; IPAL, daur ulang, TPA, TPS, kolam retensi mengurangi.','industry, coal plants, cement, smelters, mines, quarries, kilns and livestock add to it; WWTP, recycling, landfill, waste depots and retention ponds reduce it.')}</p>
  ${fxs?`<p class="note"><b>${L2('Pengaruh wilayah pada rapormu','Regional effect on your report')}:</b> ${fxs}</p>`:''}
  <h3 style="margin:12px 0 4px">🏗️ ${L2('Proyek patungan','Joint projects')}</h3><p class="note" style="margin:0 0 6px">${L2('Kas diisi dalam satuan kas gim (nilai rupiahnya tampil di sampingnya; kasmu sekarang '+Math.floor(S.res.coin)+' satuan = '+money(S.res.coin,true)+'). Sumbangan langsung dipotong dari kas/bahanmu.','Cash is entered in game cash units (the money value shows next to it; you have '+Math.floor(S.res.coin)+' units = '+money(S.res.coin,true)+'). Contributions are deducted from your cash/materials right away.')} ${L2('Bila proyek selesai, penyumbang mendapat bonus penuh, anggota lain separuh.','When a project completes, contributors get the full bonus, other members half.')}</p>
  ${j.projects.map(p=>{const rs=['coin','wood','stone'].filter(r=>p.need[r]>0),tot=rs.reduce((a,r)=>a+Math.min(1,p.got[r]/p.need[r]),0)/rs.length;return `<div class="nb" style="display:block"><div style="display:flex;justify-content:space-between;gap:8px"><b>${RP_IC[p.k]||'🏗️'} ${esc(p.n)}</b><small>${p.done?'✅ '+L2('Selesai','Done'):Math.round(tot*100)+'% · '+p.givers+' '+L2('penyumbang','contributors')}</small></div>
   <div class="pb" style="height:7px;border-radius:5px;background:rgba(0,0,0,.12);overflow:hidden;margin:5px 0"><i style="display:block;height:100%;width:${Math.round(tot*100)}%;background:#2f8f6a"></i></div>
   <small>${L2('Kebutuhan','Needs')}: ${rs.map(r=>resTxt(r,p.got[r])+' / '+resTxt(r,p.need[r])).join(' · ')}<br>${L2('Bonus','Bonus')}: ${RP_FX(p.fx)}${rs.some(r=>p.my[r]>0)?' · '+L2('Sumbanganmu','Your share')+': '+rs.filter(r=>p.my[r]>0).map(r=>resTxt(r,p.my[r])).join(', '):''}</small>
   ${p.done?'':`<div class="row" style="gap:6px;margin-top:6px;flex-wrap:wrap">${rs.map(r=>`<label style="display:flex;align-items:center;gap:4px;font-size:12px">${RES_N[r]()}<input type="number" min="0" step="${r==='coin'?10:10}" data-rg="${p.k}" data-r="${r}" style="width:80px" placeholder="0">${r==='coin'?`<small data-rgv="${p.k}" style="color:var(--muted);min-width:64px">= ${money(0,true)}</small>`:''}</label>`).join('')}<button class="bigbtn" data-give="${p.k}" style="padding:6px 12px;font-size:13px">🤝 ${L2('Sumbang','Contribute')}</button></div>`}</div>`}).join('')}
  <h3 style="margin:12px 0 4px">🏘️ ${L2('Anggota wilayah','Region members')} (${j.members.length})</h3>
  ${j.members.slice(0,40).map(m=>`<div class="nb"${m.me?' style="background:rgba(224,165,38,.14);border-radius:8px;padding-left:6px"':''}><div><b>${esc(m.name)}</b> <small>· ${esc(m.who)}</small><br><small>${esc(m.loc)} · ${t('era',{n:m.era})} · ${m.kk} KK · 🏅 ${m.nb}</small></div><div style="text-align:right"><b>${m.score}</b><br><small title="${L2('pencemaran','pollution')}">🏭 ${m.pol}</small></div></div>`).join('')||`<p>${L2('Belum ada anggota lain.','No other members yet.')}</p>`}`);
 document.querySelectorAll('[data-rg][data-r="coin"]').forEach(i=>i.oninput=()=>{const v=document.querySelector(`[data-rgv="${i.dataset.rg}"]`);if(v)v.textContent='= '+money(Math.max(0,+i.value||0),true)});
 document.querySelectorAll('[data-give]').forEach(b=>b.onclick=async()=>{const k=b.dataset.give,am={};document.querySelectorAll(`[data-rg="${k}"]`).forEach(i=>{am[i.dataset.r]=Math.max(0,+i.value||0)});
  for(const r in am){if(am[r]>(S.res[r]||0)){toast(L2(RES_N[r]()+' tidak cukup.','Not enough '+RES_N[r]().toLowerCase()+'.'));return}}if(!Object.values(am).some(v=>v>0)){toast(L2('Isi jumlah sumbangan.','Enter an amount.'));return}
  b.disabled=true;try{dirty=true;await save(true);for(let i=0;i<30&&saving;i++)await new Promise(r=>setTimeout(r,100));const g=await api('region_give',Object.assign({p:k,base:saveVer},am));
   for(const r in g.given)S.res[r]=+((S.res[r]||0)-g.given[r]).toFixed(4);saveVer=g.ver;updHUD();Snd.play(g.done?'mission':'build');
   toast('🤝 '+L2('Terima kasih! Tersumbang: ','Thanks! Contributed: ')+Object.entries(g.given).filter(([,v])=>v>0).map(([r,v])=>resTxt(r,v)).join(', ')+(g.done?L2(' — proyek selesai! 🎉',' — project complete! 🎉'):''));regionUI(true)}
  catch(e){b.disabled=false;toast(e.message==='conflict'?L2('Data berubah di tab/perangkat lain — muat ulang dulu.','Data changed elsewhere — reload first.'):e.message==='lack'?L2('Bahan di simpanan server tidak cukup.','Not enough resources in your saved game.'):e.message==='flagged'?L2('Akun sedang ditinjau pengelola; belum bisa menyumbang.','Account under review; contributions are paused.'):e.message==='done'?L2('Proyek sudah selesai.','Project already complete.'):t('errNet'))}})}

/* v51: menu ☰ dikelompokkan (akordeon) agar ramping; hanya satu kelompok terbuka */
const MENU_G=[['kampung','🏘️','Kampung & wilayah','Kampung & region',['mCity','mMetro','mBadge','mReg','mNb','mExp','mRiver','mBoard','mClass','mComp','mRep']],
 ['ekonomi','💰','Ekonomi & bahan','Economy & materials',['mWood','mSell','mBank','mNet']],
 ['belajar','📚','Belajar & bantuan','Learn & help',['mPus','mTut','mHelp','mGuide']],
 ['akun','👤','Akun & tokoh','Account & character',['mProf','mAv','mDosen']],
 ['atur','⚙️','Pengaturan','Settings',['mSet','mLite','mSnd','mLang']]];
function menuGroup(m){let open='';try{open=sessionStorage.getItem('baMenuG')||''}catch(e){}
 const tail=['mExit','mHome'].map(id=>m.querySelector('#'+id)).filter(Boolean);
 MENU_G.forEach(([k,ic,ni,ne,ids])=>{const bs=ids.map(id=>m.querySelector('#'+id)).filter(Boolean);if(!bs.length)return;
  const d=document.createElement('details');d.className='mg';d.dataset.g=k;if(open===k)d.open=true;
  d.innerHTML=`<summary>${ic} ${lang==='en'?ne:ni}<small>${bs.length}</small></summary>`;const box=document.createElement('div');box.className='mgb';bs.forEach(b=>box.appendChild(b));d.appendChild(box);m.appendChild(d);
  d.addEventListener('toggle',()=>{if(d.open){m.querySelectorAll('details.mg').forEach(o=>{if(o!==d)o.open=false});try{sessionStorage.setItem('baMenuG',k)}catch(e){}}})});
 if(tail.length){const hr=document.createElement('div');hr.className='mgt';tail.forEach(b=>hr.appendChild(b));m.appendChild(hr)}}

/* v51a: skor permukiman di bawah profil kiri atas; ketuk → rapor skor */
function hudScore(){const b=$('hScore');if(!b||!S)return;const I=S._ind,nb=Object.keys(S._badges||{}).length;
 b.innerHTML=GUEST||S.scen?`⭐ ${L2('Skor: simpan di akun','Score: save to an account')}`:I?`⭐ ${L2('Skor','Score')} ${I.score}${nb?` <em>· 🏅 ${nb}</em>`:''}`:`⭐ ${L2('Skor: simpan dulu','Score: save first')}`;
 b.onclick=e=>{e.stopPropagation();scoreUI()}}
function scoreUI(){if(GUEST||S.scen){modal(`<h2>⭐ ${L2('Skor permukiman','Settlement score')}</h2><p>${L2('Skor dinilai server untuk permainan yang tersimpan di akun (bukan tamu atau skenario latihan).','Scores are assessed by the server for games saved to an account (not guest or practice scenarios).')}</p>`);return}
 const I=S._ind,P=S._indPrev||{},R=RAPN[lang];if(!I){modal(`<h2>⭐ ${L2('Skor permukiman','Settlement score')}</h2><p>${L2('Belum dinilai. Simpan permainan untuk mendapat skor dari server.','Not assessed yet. Save your game to get a score from the server.')}</p><div class="row"><button class="bigbtn gold" id="scSave">💾 ${t('save')}</button></div>`);$('scSave').onclick=async()=>{dirty=true;await save(true);scoreUI()};return}
 const W={e:.25,n:.2,c:.2,k:.25,p:.1},kf=.35+.65*Math.min(1,S.kk/50),dl=k=>{const d=P[k]==null?0:I[k]-P[k];return d?` <small style="color:${d>0?'#2f8f6a':'#c0392b'}">${d>0?'▲':'▼'}${Math.abs(d)}</small>`:''};
 modal(`<h2>⭐ ${L2('Skor permukiman','Settlement score')}: ${I.score}${dl('score')}</h2>
  <p class="note">${L2('Dinilai server setiap kali permainan disimpan. Skor = 10 × (25% ekonomi + 20% jejaring + 20% kenyamanan + 25% kepuasan + 10% pertumbuhan) × faktor jumlah KK (penuh mulai 50 KK; sekarang','Assessed by the server on every save. Score = 10 × (25% economy + 20% network + 20% comfort + 25% satisfaction + 10% growth) × household factor (full from 50 households; now')} ${Math.round(kf*100)}%).</p>
  ${['e','n','c','k','p'].map(k=>`<div class="kv" style="align-items:center"><span style="min-width:120px">${R[k]} <small>(${Math.round(W[k]*100)}%)</small></span><div style="flex:1;height:8px;border-radius:5px;background:rgba(0,0,0,.12);overflow:hidden;margin:0 8px"><i style="display:block;height:100%;width:${I[k]}%;background:#2f8f6a"></i></div><b>${I[k]}</b>${dl(k)}</div>`).join('')}
  ${I.rth!=null?`<div class="kv"><span>RTH</span><b>${I.rth}%</b></div><div class="kv"><span>${L2('Layanan kota','City services')}</span><b>${I.svc}</b></div>`:''}
  <div class="kv"><span>🏅 ${L2('Lencana','Badges')}</span><b>${Object.keys(S._badges||{}).length}/${BADGES.length}</b></div>${S._river!=null?`<div class="kv"><span>🌊 ${L2('Sungai wilayah','Regional river')}</span><b>${S._river}/100</b></div>`:''}
  <p class="note" style="margin-top:8px">${L2('Ketuk baris rapor di panel Misi untuk melihat penyebab & cara menaikkan tiap indikator.','Tap a report row in the Missions panel to see causes & how to raise each indicator.')}</p>
  <div class="row" style="gap:6px;flex-wrap:wrap"><button class="bigbtn alt" id="scBoard">🏆 ${lt('h')}</button><button class="bigbtn alt" id="scBadge">🏅 ${L2('Lencana','Badges')}</button><button class="bigbtn alt" id="scReg">🗺️ ${L2('Wilayah','Region')}</button><button class="bigbtn alt" id="scSave">💾 ${L2('Simpan & nilai ulang','Save & reassess')}</button></div>`);
 $('scBoard').onclick=()=>board();$('scBadge').onclick=()=>badgesUI();$('scReg').onclick=()=>regionUI();$('scSave').onclick=async()=>{dirty=true;await save(true);scoreUI()}}

/* v51b: lembar "Semua alat" — semua alat dalam kategori sebagai kisi, praktis di ponsel & tablet */
function toolGrid(){let o=$('toolSheet');if(o){o.remove();return}const C=CATS.find(c=>c.k===curCat)||CATS[0],li=lang==='en'?1:0;
 const ks=catTools(curCat).slice().sort((x,y)=>((BT[x]&&BT[x].era>S.era)?1:0)-((BT[y]&&BT[y].era>S.era)?1:0));
 o=document.createElement('div');o.id='toolSheet';o.innerHTML=`<div class="tsh"><b>${C.ic} ${C.n[li]}</b><span>${ks.length} ${L2('alat','tools')}</span><button class="tsx" aria-label="${L2('Tutup','Close')}">✕</button></div><div class="tsg">${ks.map(k=>{const T=BT[k],lock=T&&T.era>S.era,c=T?T.c:null;
  return `<button class="tsi${k===tool?' on':''}${lock?' lock':''}" data-k="${k}"><i>${ICON[k]}</i><b>${tlN(k)}</b><em>${lock?'🔒 Era '+T.era:c?costTxt(c):k==='babat'?L2('gratis','free'):k==='path'?money(1,true):''}</em></button>`}).join('')}</div>`;
 document.body.appendChild(o);o.querySelector('.tsx').onclick=()=>o.remove();
 o.querySelectorAll('.tsi').forEach(b=>b.onclick=()=>{const k=b.dataset.k,T=BT[k];if(T&&T.era>S.era){toast(t('locked',{n:T.era}));return}o.remove();const tb=$('bar').querySelector(`.tool[data-k="${k}"]`);if(tb){tb.click();tb.scrollIntoView({inline:'center',block:'nearest'})}})}
document.addEventListener('pointerdown',e=>{const o=$('toolSheet');if(o&&!o.contains(e.target)&&!e.target.closest('#gridBtn'))o.remove()},true);
